import{_ as a,o as r,c as t,a2 as s}from"./chunks/framework.eFe5Lsvn.js";const c=JSON.parse('{"title":"Markers and pose variables","description":"","frontmatter":{},"headers":[],"relativePath":"app/markers.md","filePath":"app/markers.md"}'),o={name:"app/markers.md"};function n(i,e,l,p,d,h){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="markers-and-pose-variables" tabindex="-1">Markers and pose variables <a class="header-anchor" href="#markers-and-pose-variables" aria-label="Permalink to &quot;Markers and pose variables&quot;">​</a></h1><h2 id="event-markers" tabindex="-1">Event markers <a class="header-anchor" href="#event-markers" aria-label="Permalink to &quot;Event markers&quot;">​</a></h2><p>Click <strong>+</strong> next to <em>Event markers</em> in the sidebar. A marker is a name plus a command bound in robot code, placed at a waypoint with a time offset. A <strong>zone marker</strong> stays active until its end point.</p><ul><li><strong>If bump recovery skips it:</strong> fire when rejoining (the default), fire immediately, or skip.</li><li><strong>Must hit:</strong> recovery can never jump past this marker&#39;s time.</li></ul><p>Marker ticks show in amber on the timeline. In robot code they run bound commands or trigger <code>atTime(...)</code>. See <a href="/Mayhem/lib/markers">Event markers</a>.</p><h2 id="pose-variables" tabindex="-1">Pose variables <a class="header-anchor" href="#pose-variables" aria-label="Permalink to &quot;Pose variables&quot;">​</a></h2><p>Pose variables are named poses shared by every path in the project, for example a shooting spot or an intake station.</p><ul><li><strong>Create one.</strong> Open <strong>Pose variables</strong> beside the Constraint button, then click <strong>New pose variable</strong>. If a waypoint is selected, the new variable starts at its pose and links to it. You can also click <strong>Save as</strong> in the waypoint panel.</li><li><strong>Link a waypoint.</strong> Use the waypoint panel&#39;s <em>Pose variable</em> menu. Linked waypoints show a ring.</li><li><strong>Move one.</strong> Moving a linked waypoint, or editing the variable, moves it in <strong>every</strong> path that uses it. Those paths are marked out of date.</li></ul><h2 id="folders" tabindex="-1">Folders <a class="header-anchor" href="#folders" aria-label="Permalink to &quot;Folders&quot;">​</a></h2><p>Organize paths with the folder button in the <em>Paths</em> header, and drag paths into folders.</p>',10)])])}const k=a(o,[["render",n]]);export{c as __pageData,k as default};
